import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import Sidebar from "../components/Sidebar";

function UnitTest() {
  const { subId } = useParams();
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user"));

  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [result, setResult] = useState(null);

  useEffect(() => {
    if (!user) return;
    async function load() {
      try {
        const res = await fetch(`http://localhost:8080/unit_tests/questions/${subId}`);
        const data = await res.json();
        setQuestions(data.questions || []);
      } catch (err) {
        console.error("UnitTest load error:", err);
      } finally {
        setLoading(false);
      }
    }

    load();
  }, [subId, user]);

  if (!user) return <h1 style={{ color: "white" }}>Please log in</h1>;

  function handleChange(qId, value) {
    setAnswers((p) => ({ ...p, [qId]: value }));
  }

  async function handleSubmit(e) {
    e.preventDefault();
    setSubmitting(true);
    try {
      const res = await fetch("http://localhost:8080/unit_tests/submit", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: user.id, sub_id: subId, answers }),
      });
      const data = await res.json();
      if (res.ok) {
        setResult(data);
      } else {
        alert(data.message || "Submit failed");
      }
    } catch (err) {
      console.error(err);
      alert("Submission error");
    } finally {
      setSubmitting(false);
    }
  }

  if (loading) return <p className="dashboard-loading">Loading test...</p>;

  if (result) {
    return (
      <div className="dashboard-page">
        <Sidebar />
        <main className="dashboard-main">
          <section className="dashboard-panel">
            <h1>Unit Test Results</h1>
            <p>Score: {result.score}%</p>
            <p>Correct: {result.correct} / {result.total}</p>
            <p>Earned XP: {result.xp || 0} • Earned Coins: {result.coins || 0}</p>
            <button className="primary-btn" onClick={() => navigate(`/subscience/${subId}`)}>Return to Unit</button>
          </section>
        </main>
      </div>
    );
  }

  return (
    <div className="dashboard-page">
      <Sidebar />
      <main className="dashboard-main">
        <header className="dashboard-header">
          <div>
            <h1>Unit Test</h1>
            <p className="dashboard-subtitle">25 questions — do your best. Answers are saved when you submit.</p>
          </div>
        </header>

        <form className="card" onSubmit={handleSubmit}>
          {questions.map((q, i) => (
            <label key={q.id} style={{ display: "block", marginBottom: 12 }}>
              <div style={{ fontWeight: 600 }}>{i + 1}. {q.question}</div>
              {q.type === "mcq" ? (
                <div style={{ marginTop: 6 }}>
                  {(q.options || []).map((opt) => (
                    <div key={opt}>
                      <label>
                        <input type="radio" name={`q-${q.id}`} value={opt} checked={answers[q.id] === opt} onChange={() => handleChange(q.id, opt)} /> {opt}
                      </label>
                    </div>
                  ))}
                </div>
              ) : (
                <textarea value={answers[q.id] || ""} onChange={(e) => handleChange(q.id, e.target.value)} rows={3} />
              )}
            </label>
          ))}

          <div style={{ display: "flex", gap: 8 }}>
            <button className="primary-btn" type="submit" disabled={submitting}>{submitting ? "Submitting..." : "Submit Test"}</button>
            <button type="button" className="ghost-btn" onClick={() => navigate(-1)}>Cancel</button>
          </div>
        </form>
      </main>
    </div>
  );
}

export default UnitTest;
